legacy:
function sum(a, b) {
  var total = a + b;
  return total;
}

modern:
function sum(a, b) {
  const total = a + b;
  return total;
}

legacy:
function greet(name) {
  return 'Hello, ' + name + '!';
}

modern:
function greet(name) {
  return `Hello, ${name}!`;
}

legacy:
function double(n) {
  return n * 2;
}
module.exports = { double };

const fs = require('fs');
function read(path) {
  return fs.readFileSync(path, 'utf8');
}
module.exports = { read };

modern:
import fs from 'node:fs';

export function read(path) {
  return fs.readFileSync(path, 'utf8');
}

legacy:
function loadUser(id) {
  return new Promise(function(resolve, reject) {
    fetch('/api/users/' + id).then(function(res) {
      return res.json();
    }).then(resolve).catch(reject);
  });
}

modern:
async function loadUser(id) {
  const res = await fetch(`/api/users/${id}`);
  return res.json();
}

legacy:
function joinNames(people) {
  var out = [];
  for (var i = 0; i < people.length; i++) {
    out.push(people[i].name);
  }
  return out.join(', ');
}

modern:
function joinNames(people) {
  const out = [];
  for (const person of people) {
    out.push(person.name);
  }
  return out.join(', ');
}

legacy:
function ids(items) {
  var result = [];
  for (var i = 0; i < items.length; i++) {
    result.push(items[i].id);
  }
  return result;
}

modern:
function ids(items) {
  return items.map((item) => item.id);
}

legacy:
function isReady(flag) {
  if (flag == true) {
    return 'yes';
  }
  return 'no';
}

modern:
function isReady(flag) {
  if (flag === true) {
    return 'yes';
  }
  return 'no';
}

legacy:
function withDefaults(opts) {
  return Object.assign({}, { retries: 3 }, opts);
}

modern:
function withDefaults(opts) {
  return { retries: 3, ...opts };
}

legacy:
function getJSON(url, cb) {
  fetch(url).then(function(r) { return r.json(); }).then(function(data) {
    cb(null, data);
  }).catch(function(err) {
    cb(err);
  });
}

modern:
async function getJSON(url) {
  const r = await fetch(url);
  return r.json();
}

legacy:
function Counter(start) {
  this.value = start || 0;
}
Counter.prototype.inc = function() {
  this.value += 1;
  return this.value;
};
module.exports = Counter;

modern:
export class Counter {
  constructor(start = 0) {
    this.value = start;
  }

  inc() {
    this.value += 1;
    return this.value;
  }
}

legacy:
function city(user) {
  if (user && user.address && user.address.city) {
    return user.address.city;
  }
  return 'unknown';
}

modern:
function city(user) {
  return user?.address?.city ?? 'unknown';
}

legacy:
function port(env) {
  return env.PORT || 3000;
}

modern:
function port(env) {
  return env.PORT ?? 3000;
}

legacy:
function label(user) {
  return user.firstName + ' ' + user.lastName;
}

modern:
function label(user) {
  const { firstName, lastName } = user;
  return `${firstName} ${lastName}`;
}

legacy:
function allowed(role) {
  var roles = ['admin', 'editor'];
  return roles.indexOf(role) !== -1;
}

modern:
function allowed(role) {
  const roles = ['admin', 'editor'];
  return roles.includes(role);
}

legacy:
function toInt(raw) {
  return parseInt(raw);
}

modern:
function toInt(raw) {
  return Number.parseInt(raw, 10);
}

legacy:
export function add(a, b) {
  return a + b;
}

modern:
export function add(a: number, b: number): number {
  return a + b;
}

legacy:
export function parse(raw: any) {
  return JSON.parse(raw);
}

modern:
export function parse(raw: string): unknown {
  return JSON.parse(raw);
}

legacy:
export class Box {
  value: number;
  constructor(v: number) {
    this.value = v;
  }
}

modern:
export class Box {
  constructor(public value: number) {}
}

legacy:
function msg(user, action) {
  return user + ' performed ' + action;
}

modern:
function msg(user, action) {
  return `${user} performed ${action}`;
}

legacy:
(function() {
  function ping() { return 'pong'; }
  module.exports = { ping };
})();

modern:
export function ping() {
  return 'pong';
}

legacy:
function isHttp(url) {
  return url.indexOf('http') === 0;
}

modern:
function isHttp(url) {
  return url.startsWith('http');
}

legacy:
function isJs(file) {
  return file.slice(-3) === '.js';
}

modern:
function isJs(file) {
  return file.endsWith('.js');
}

legacy:
function paginate(page, size) {
  page = page || 1;
  size = size || 20;
  return { page: page, size: size };
}

modern:
function paginate(page = 1, size = 20) {
  return { page, size };
}

legacy:
function pair(a, b) {
  return { a: a, b: b };
}

modern:
function pair(a, b) {
  return { a, b };
}

legacy:
function sum(arr) {
  var total = 0;
  for (var i = 0; i < arr.length; i++) {
    total += arr[i];
  }
  return total;
}

modern:
function sum(arr) {
  let total = 0;
  for (let i = 0; i < arr.length; i++) {
    total += arr[i];
  }
  return total;
}

legacy:
function MathUtil() {}
MathUtil.add = function(a, b) { return a + b; };
module.exports = MathUtil;

modern:
export class MathUtil {
  static add(a, b) {
    return a + b;
  }
}

legacy:
function api(path) {
  return fetch(path).then(function(r) {
    if (!r.ok) throw new Error('bad');
    return r.json();
  });
}

modern:
async function api(path) {
  const r = await fetch(path);
  if (!r.ok) throw new Error('bad');
  return r.json();
}

legacy:
function activeNames(users) {
  var names = [];
  for (var i = 0; i < users.length; i++) {
    if (users[i].active) names.push(users[i].name);
  }
  return names;
}

modern:
function activeNames(users) {
  return users.filter((u) => u.active).map((u) => u.name);
}

legacy:
function max() {
  var args = Array.prototype.slice.call(arguments);
  return Math.max.apply(null, args);
}

modern:
function max(...args) {
  return Math.max(...args);
}

legacy:
function on(flag) {
  return flag ? true : false;
}

modern:
function on(flag) {
  return Boolean(flag);
}

legacy:
function safeParse(raw) {
  try { return JSON.parse(raw); } catch (e) { return null; }
}

modern:
function safeParse(raw) {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

legacy:
const url = require('url');
function host(href) {
  return url.parse(href).host;
}
module.exports = { host };

modern:
export function host(href) {
  return new URL(href).host;
}

legacy:
function bytes(text) {
  return new Buffer(text);
}

modern:
function bytes(text) {
  return Buffer.from(text);
}

legacy:
function bad(n) {
  return isNaN(n);
}

modern:
function bad(n) {
  return Number.isNaN(n);
}

legacy:
function keys(obj) {
  var out = [];
  for (var k in obj) {
    if (obj.hasOwnProperty(k)) out.push(k);
  }
  return out;
}

modern:
function keys(obj) {
  return Object.keys(obj);
}

legacy:
function unique(items) {
  var seen = {};
  var out = [];
  for (var i = 0; i < items.length; i++) {
    var v = items[i];
    if (!seen[v]) { seen[v] = true; out.push(v); }
  }
  return out;
}

modern:
function unique(items) {
  return [...new Set(items)];
}

legacy:
function Wallet() {
  this._balance = 0;
}
Wallet.prototype.credit = function(n) {
  this._balance += n;
};
module.exports = Wallet;

modern:
export class Wallet {
  #balance = 0;

  credit(n) {
    this.#balance += n;
  }
}

legacy:
function delay(ms, cb) {
  setTimeout(function() { cb(null); }, ms);
}

modern:
function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

legacy:
const { readFile } = require('fs').promises;
async function load(p) { return readFile(p, 'utf8'); }
module.exports = { load };

modern:
import { readFile } from 'node:fs/promises';

export async function load(p) {
  return readFile(p, 'utf8');
}

legacy:
function total(cart) {
  var sum = 0;
  for (var i = 0; i < cart.length; i++) {
    sum += cart[i].price;
  }
  return sum;
}

modern:
function total(cart) {
  return cart.reduce((sum, item) => sum + item.price, 0);
}

legacy:
function allTags(posts) {
  var tags = [];
  for (var i = 0; i < posts.length; i++) {
    tags = tags.concat(posts[i].tags);
  }
  return tags;
}

modern:
function allTags(posts) {
  return posts.flatMap((post) => post.tags);
}

